const SCORE_WITHOUT_SPHINX = 0;
const SPHINX_POINT = 1;
const POINT_PER_TYPE = 1;
const TYPE_THRESHOLD = 3;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === "sphinx");

const countTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countTypesBeyondThreshold = (army: Card[]): number =>
  Math.max(countTypes(army) - TYPE_THRESHOLD, 0);

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return SCORE_WITHOUT_SPHINX;
  return (
    SPHINX_POINT +
    POINT_PER_TYPE * Math.max(countTypesBeyondThreshold(army), 1)
  );
};

